import {call as fetchMany} from 'core/ajax';
import {debugLog} from 'local_processfeedback/utils/logger';

export const fetchBootstrapData = (contextid, cmid) => {
    debugLog(null, 'Bootstrap AJAX request queued', {
        contextid,
        cmid,
    });
    return fetchMany([{
        methodname: 'local_processfeedback_get_bootstrap_data',
        args: {
            contextid,
            cmid,
        },
    }])[0];
};
